def add(a, b):
    return a + b


def subtract(a, b):
    return a - b


def _unused_legacy_multiply(a, b):
    # replaced by the `*` operator everywhere; nothing calls this anymore
    result = 0
    for _ in range(b):
        result += a
    return result


def average(values):
    return sum(values) / len(values)
